CREATE FUNCTION public.get_revenue_document(p_event_id text) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE scope jsonb; e public.revenue_events; r jsonb; url text; BEGIN
scope:=public.revenue_scope(); SELECT * INTO e FROM public.revenue_events WHERE id=p_event_id;
IF NOT FOUND OR (NOT (scope->>'admin')::boolean AND e.location IS DISTINCT FROM scope->>'location') THEN RAISE EXCEPTION 'Kein Zugriff auf diesen Beleg' USING ERRCODE='42501'; END IF;
CASE e.source_table WHEN 'inquiry_invoices' THEN SELECT to_jsonb(x) INTO r FROM public.inquiry_invoices x WHERE id=e.source_id; WHEN 'b2b_invoices' THEN SELECT to_jsonb(x) INTO r FROM public.b2b_invoices x WHERE id=e.source_id; WHEN 'b2b_offers' THEN SELECT to_jsonb(x) INTO r FROM public.b2b_offers x WHERE id=e.source_id; WHEN 'rental_inquiries' THEN SELECT to_jsonb(x) INTO r FROM public.rental_inquiries x WHERE id=e.source_id; WHEN 'sales_inquiries' THEN SELECT to_jsonb(x) INTO r FROM public.sales_inquiries x WHERE id=e.source_id; ELSE RAISE EXCEPTION 'Beleg nicht vorhanden'; END CASE;
IF e.stage='invoiced' THEN url:=coalesce(nullif(r->>'file_url',''),r->>'file_path'); ELSIF e.source_table='b2b_offers' THEN url:=r->>'file_url'; ELSIF r->'original_accepted_offer'->>'offer_number'=e.document_number THEN url:=r->'original_accepted_offer'->>'offer_file_url'; ELSIF r->>'offer_number'=e.document_number THEN url:=r->>'offer_file_url'; END IF;
IF url IS NULL THEN RAISE EXCEPTION 'Für diese historische Fassung ist kein eindeutiges PDF gespeichert'; END IF;
RETURN jsonb_build_object('url',url,'source_table',e.source_table,'source_id',e.source_id,'credit_note',e.event_kind='credit_note'); END $$;
REVOKE ALL ON FUNCTION public.get_revenue_document(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.get_revenue_document(text) TO authenticated,service_role;